using Marina.Domain.Catalog; using Marina.Domain.Security; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore;
namespace Marina.Persistence.Data;
public static class DatabaseSeeder{
 public static readonly string[]Roles=["SuperAdmin","Admin","StoreManager","InventoryManager","OrderManager","ProductManager","CustomerSupport","Customer"];
 public static readonly string[]Permissions=["Products.View","Products.Create","Products.Edit","Products.Delete","Inventory.View","Inventory.Adjust","Orders.View","Orders.UpdateStatus","Orders.Cancel","Customers.View","Coupons.Manage","Notifications.Manage","Users.Manage","Roles.Manage","Reports.View","AuditLogs.View","Settings.Manage"];
 public static async Task SeedAsync(MarinaDbContext db,RoleManager<IdentityRole<Guid>>roleManager,CancellationToken ct=default){var newRoles=new HashSet<string>();foreach(var name in Roles)if(!await roleManager.RoleExistsAsync(name)){var created=await roleManager.CreateAsync(new IdentityRole<Guid>(name));if(!created.Succeeded)throw new InvalidOperationException("Role initialization failed.");newRoles.Add(name);}foreach(var name in Permissions)if(!await db.Permissions.AnyAsync(x=>x.Name==name,ct))db.Permissions.Add(new Permission{Name=name,Description=name.Replace('.',' ')});await db.SaveChangesAsync(ct);var allPermissions=await db.Permissions.ToDictionaryAsync(x=>x.Name,x=>x.Id,ct);var grants=new Dictionary<string,string[]>{["SuperAdmin"]=Permissions,["Admin"]=Permissions,["StoreManager"]=Permissions.Where(x=>x is not "Users.Manage" and not "Roles.Manage").ToArray(),["ProductManager"]=["Products.View","Products.Create","Products.Edit"],["InventoryManager"]=["Products.View","Inventory.View","Inventory.Adjust"],["OrderManager"]=["Orders.View","Orders.UpdateStatus","Orders.Cancel"],["CustomerSupport"]=["Orders.View","Customers.View"]};foreach(var(roleName,names)in grants){if(!newRoles.Contains(roleName))continue;var role=await roleManager.FindByNameAsync(roleName);if(role is null)continue;foreach(var name in names){var permissionId=allPermissions[name];if(!await db.RolePermissions.AnyAsync(x=>x.RoleId==role.Id&&x.PermissionId==permissionId,ct))db.RolePermissions.Add(new RolePermission{RoleId=role.Id,PermissionId=permissionId});}}if(!await db.Categories.AnyAsync(ct)){var clothing=new Category{Slug="clothing",SortOrder=1,Translations=[new CategoryTranslation{Culture="en",Name="Clothing"},new CategoryTranslation{Culture="ar",Name="ملابس"}]};clothing.Children.Add(new Category{Slug="girls",SortOrder=1,Translations=[new CategoryTranslation{Culture="en",Name="Girls"},new CategoryTranslation{Culture="ar",Name="بناتي"}]});clothing.Children.Add(new Category{Slug="boys",SortOrder=2,Translations=[new CategoryTranslation{Culture="en",Name="Boys"},new CategoryTranslation{Culture="ar",Name="ولادي"}]});db.Categories.Add(clothing);db.Categories.Add(new Category{Slug="shoes",SortOrder=2,Translations=[new CategoryTranslation{Culture="en",Name="Shoes"},new CategoryTranslation{Culture="ar",Name="أحذية"}]});db.Categories.Add(new Category{Slug="dresses",SortOrder=3,Translations=[new CategoryTranslation{Culture="en",Name="Dresses"},new CategoryTranslation{Culture="ar",Name="فساتين"}]});}if(!await db.AppSettings.AnyAsync(x=>x.Key=="MaintenanceMode",ct))db.AppSettings.Add(new AppSetting{Key="MaintenanceMode",Value="false",IsPublic=true});if(!await db.AppSettings.AnyAsync(x=>x.Key=="SupportEmail",ct))db.AppSettings.Add(new AppSetting{Key="SupportEmail",Value="support@marina.invalid",IsPublic=true});await db.SaveChangesAsync(ct);}
}
